                if s.startswith('(') and 'Zip Code' in s:
                    prev=nonempty_prev(lines,j)
                    if prev and prev not in parts and prev.strip() "'!= lines[i-1].strip():
                        if not phone_re.search(prev):
                            parts.append(prev.strip())
                    break
                if s.startswith('"'(') or 'telephone number' in s.lower() or 'Securities registered' in s:
                    break
                if re.fullmatch(r'[A-Z]{2,}[ ]?[0-9A-Z-]{3,}|\\d{5}(?:-\\d{4})?|[A-Z]{1,3}\\d[A-Z0-9 ]{2,}', s):
                    # likely zip/postcode line
                    if s not in parts:
                        parts.append(s)
            parts=[p for p in parts if p]
            if parts:
                return ', '.join(parts)
    return 'NOT_FOUND'

exchange_markers=['New York Stock Exchange','Nasdaq','NASDAQ','Nasdaq Global Select Market','The Nasdaq Stock Market LLC','NYSE American']

def extract_trading(lines, text):
    start=end=None
    for i,l in enumerate(lines[:HEADER_LIMIT]):
        if 'Securities registered pursuant to Section' in l and '12(b)' in l:
            start=i
        if start is not None and 'Securities registered pursuant to Section' in l and '12(g)' in l:
            end=i
            break
        if start is not None and 'Securities registered pursuant to section 12(g)' in l.lower():
            end=i; break
    pairs=[]
    if start is not None:
        block=[x.strip() for x in lines[start+1:(end if end else start+25)] if x.strip()]
        # drop headers
        filtered=[]
        for s in block:
            if re.search(r'"'^(Title of|Trading Symbol|Trading symbol|Name of Each Exchange|Name of each exchange|on which registered|'"\\(Title|\\(Trading|\\(Name)', s, re.I):
                continue
            filtered.append(s)
        for idx,s in enumerate(filtered):
            if any(m in s for m in exchange_markers):
                exch=s
                sym=filtered[idx-1] if idx>0 else ''
                if sym and not any(m in sym for m in exchange_markers) and 'Common Stock' not in sym and 'Ordinary Shares' not in sym and 'Notes due' not in sym and 'par value' not in sym and sym not in {'—','-','None'} and not sym.startswith('1.'):
                    pairs.append((sym,exch))
        # special case if pairs empty and single exchange line present
        if not pairs:
            exch=''
            for s in filtered:
                if any(m in s for m in exchange_markers): exch=s
            m=re.search(r'ticker symbol\\s+\"([A-Z./-]+)\"', text[:20000], re.I) or re.search(r'under the symbol\\s+\"?([A-Z./-]+)\"?', text[:30000], re.I)
            if not m:
                m=re.search(r'\\b([A-Z]{1,5})\\b\\s+New York Stock Exchange', ' '.join(filtered))
            if m and exch:
                pairs.append((m.group(1), exch))
    if not pairs:
        # fallback early text
        m=re.search(r'ticker symbol\\s+\"([A-Z./-]+)\"', text[:40000], re.I) or re.search(r'under the symbol\\s+\"?([A-Z./-]+)\"?', text[:40000], re.I)
        exch=''
        for em in exchange_markers:
            if em in text[:4000]: exch=em; break
        if m and exch:
            pairs.append((m.group(1), exch))
    # dedupe, skip em dash symbols
    out=[]; seen=set()
    for sym,exch in pairs:
        sym=sym.strip(' :')
        exch=exch.strip(' :')
        if sym in {'—','-',''}: continue
        key=(sym,exch)
        if key not in seen:
            seen.add(key)
            out.append(f'{sym} - {exch}')
    return '; '.join(out) if out else 'NOT_FOUND'

# statement helpers
statement_headers_income=[
    'CONSOLIDATED STATEMENTS OF OPERATIONS',
    'Consolidated Statements of Operations',
    'CONSOLIDATED STATEMENTS OF INCOME',
    'Consolidated Statements of Income',
    'CONSOLIDATED STATEMENTS OF EARNINGS',
    'Consolidated Statements of Earnings',
    'STATEMENTS OF CONSOLIDATED INCOME',
    'Statements of Consolidated Income',
    'CONSOLIDATED STATEMENT OF EARNINGS',
    'Consolidated Statement of Earnings',
]
statement_headers_balance=[
    'CONSOLIDATED BALANCE SHEETS',
    'Consolidated Balance Sheets',
    'CONSOLIDATED STATEMENTS OF FINANCIAL POSITION',
    'Consolidated Statements of Financial Position',
]

def find_statement_snippet(text, headers, must_have):
    candidates=[]
    for h in headers:
        start=0
        while True:
            idx=text.find(h, start)
            if idx==-1: break
            snippet=text[idx:idx+5000]
            score=sum(1 for m in must_have if m.lower() in snippet.lower())
            if score:
                candidates.append((score, idx, snippet))
            start=idx+1
    if not candidates:
        return ''
    candidates.sort(key=lambda x:(x[0], x[1]))
    return candidates[-1][2]

amount_pat = r'\\(?\\"'$?'"\\s*[\\d,.]+\\)?'

def extract_first_amount_after(label, snippet):
    # within 200 chars after label
    m=re.search(re.escape(label)+r'\\s*(?:[:\\-])?\\s*(?:\\"'$'"\\s*)?('+amount_pat+')', snippet, re.I|re.S)
    if m:
        return clean_amount(m.group(1))
    return None

def clean_amount(a):
    a=a.strip()
    a=re.sub(r'\\s+','',a)
    a=a.replace('"'$'"','')
    return a

revenue_labels=['Total revenue','Total revenues','Total net sales','Net sales','Revenues','Sales and other operating revenues']
net_labels=['Net income attributable to','Net earnings attributable to','Net income available to','Net earnings available to','Net income','Net earnings','Net loss attributable to','Net loss available to','Net loss']
debt_labels=['Long-term debt and finance lease liabilities','Long-term debt, excluding current maturities','Long-term debt, less current portion','Long-term debt excluding current installments','Long-term debt excluding current maturities','Long-term debt, excluding current portion','Long-term debt','Long-term borrowings']

def extract_revenue(text):
    snippet=find_statement_snippet(text, statement_headers_income, ['net income','net earnings','net loss','revenue','net sales','sales'])
    if not snippet: return 'NOT_FOUND'
    for label in revenue_labels:
        m=re.search(re.escape(label)+r'\\s*(?:[:\\-])?\\s*\\"'$?'"\\s*\\(?([\\d,.]+)\\)?', snippet, re.I|re.S)
        if m:
            val=clean_amount(m.group(1))
            if val and re.search(r'\\d', val):
                return val if not '(' in m.group(0) else '('+val.strip('()')+')'
    return 'NOT_FOUND'

def extract_net_income(text):
    snippet=find_statement_snippet(text, statement_headers_income, ['net income','net earnings','net loss'])
    if not snippet: return 'NOT_FOUND'
    matches=[]
    for pat in [r'Net income attributable to["'^'"\\n]*', r'Net earnings attributable to["'^'"\\n]*', r'Net income available to["'^'"\\n]*', r'Net earnings available to["'^'"\\n]*', r'Net income', r'Net earnings', r'Net loss attributable to["'^'"\\n]*', r'Net loss available to["'^'"\\n]*', r'Net loss']:
        for m in re.finditer(pat+r'\\s*(?:[:\\-])?\\s*\\"'$?'"\\s*(\\(?[\\d,.]+\\)?)', snippet, re.I|re.S):
            matches.append((m.start(), clean_amount(m.group(1)), 'loss' in m.group(0).lower()))
    if matches:
        pos,val,is_loss=sorted(matches,key=lambda x:x[0])[-1]
        if is_loss and not val.startswith('('):
            return f'({val})'
        return val
    return 'NOT_FOUND'

def extract_total_assets(text):
    snippet=find_statement_snippet(text, statement_headers_balance, ['total assets','assets'])
    if not snippet: return 'NOT_FOUND'
    m=re.search(r'Total assets\\s*\\"'$?'"\\s*(\\(?[\\d,.]+\\)?)', snippet, re.I|re.S)
    if m:
        return clean_amount(m.group(1))
    return 'NOT_FOUND'

def extract_long_term_debt(text):
    snippet=find_statement_snippet(text, statement_headers_balance, ['liabilities','debt'])
    if not snippet:
        return 'NOT_FOUND'
    for label in debt_labels:
        for m in re.finditer(re.escape(label)+r'\\s*(?:[:\\-])?\\s*\\"'$?'"\\s*(\\(?[\\d,.]+\\)?)', snippet, re.I|re.S):
            val=clean_amount(m.group(1))
            # avoid rows that are headers without numbers or current portion labels by label ordering
            if val:
                return '0' if val in {'—','-'} else val
    # if debt note says none maybe 0? search balance snippet for no long-term debt phrase
    if 'long-term debt' not in snippet.lower() and 'long-term borrowings' not in snippet.lower():
        return '0'
    return 'NOT_FOUND'

for d in data['documents']:
    text=norm(Path(d['doc_path']).read_text(errors='ignore'))
    lines=text.splitlines()
    ans={
        'name': extract_name(lines),
        'phone': extract_phone(lines),
        'state_ein': extract_state_ein(lines),
        'address': extract_address(lines),
        'trading': extract_trading(lines, text),
        'shares': 'TODO',
        'revenue': extract_revenue(text),
        'net': extract_net_income(text),
        'assets': extract_total_assets(text),
        'debt': extract_long_term_debt(text),
    }
    # shares
    header='\\n'.join(lines[:260])
    share=None
    pats=[
        r'As of ["'^.'"\\n]{0,100}?,\\s*([\\d,.]+)\\s+shares? of ["'^.'"\\n]*?outstanding',
        r'The number of shares of ["'^.'"\\n]*?outstanding as of ["'^.'"\\n]{0,100}? was\\s*([\\d,.]+)',
        r'([\\d,.]+)\\s+shares of common stock were issued and outstanding as of',
        r'As of ["'^.'"\\n]{0,100}?, the Registrant had\\s*([\\d,.]+)\\s+shares issued and outstanding',
        r'Number of shares of common stock outstanding as of ["'^.'"\\n]{0,100}\\s*\\"'$?'"\\s*([\\d,.]+)',
    ]
    for pat in pats:
        m=re.search(pat, header, re.I|re.S)
        if m:
            share=m.group(1)
            break
    if not share:
        for i,l in enumerate(lines[:220]):
            if 'number of shares' in l.lower() and 'outstanding' in l.lower():
                nums=[]
                for s in lines[i:i+12]:
                    ms=re.findall(r'\\b\\d[\\d,.]*\\b', s)
                    nums.extend(ms)
                if nums:
                    share=nums[-1]
                    break
    ans['shares']=share or 'NOT_FOUND'
    print(d['doc_name'], json.dumps(ans, ensure_ascii=False))
