import json, re
from pathlib import Path

manifest=Path('/mnt/data/LSF/baseline_results/financebench/agentic_codex_qa_gpt54_all/single_cluster/all_docs/logs/all_docs.manifest.json')
data=json.loads(manifest.read_text())

def normalize_text(t):
    return t.replace('\\xa0',' ').replace('’',\"'\").replace('“','\"').replace('”','\"').replace('–','-').replace('—','—')

def strip(s):
    return s.strip().replace('\\xa0',' ')

amount_token_re=re.compile(r'\\(?\\d[\\d,]*\\.?\\d*\\)?|—|-')
year_re=re.compile(r'\\b(19|20)\\d{2}\\b')
phone_re=re.compile(r'(\\+?\\(?\\d{2,4}\\)?[\\s.-]*\\d{3}[\\s.-]*\\d{4,5})')
ein_re=re.compile(r'\\b\\d{2}-\\d{7}\\b')

income_headers=['consolidated statements of operations','consolidated statements of income','consolidated statements of earnings','statements of consolidated income','consolidated statement of earnings']
balance_headers=['consolidated balance sheets','consolidated statements of financial position']

revenue_labels=['total revenue','total revenues','total net sales','net sales','net revenues','revenues','net revenue','sales to customers','revenue']
net_labels=['net income attributable to','net earnings attributable to','net income available to','net earnings available to','net income attributable to intel','net income','net earnings','net loss attributable to','net loss available to','net loss']
assets_labels=['total assets']
debt_labels=['total long-term debt','long-term debt and finance lease liabilities','long-term debt, net of current portion','long-term debt, less current portion','long-term debt excluding current installments','long-term debt excluding current maturities','long-term debt','long-term borrowings','term debt','debt']

company_fallbacks={
'ACTIVISIONBLIZZARD':'ACTIVISION BLIZZARD, INC.',
'FOOTLOCKER':'FOOT LOCKER, INC.',
'JOHNSON_JOHNSON':'JOHNSON & JOHNSON',
}

def count_amountish(lines):
    c=0
    for s in lines:
        s=strip(s)
        if re.fullmatch(r'["'$ ]*'"\\(?\\d[\\d,]*\\.?\\d*\\)?%?', s):
            c+=1
    return c

def find_section_start(lines, headers):
    cands=[]
    low=[strip(l).lower() for l in lines]
    for i,l in enumerate(low):
        if any(h==l or h in l for h in headers):
            window=lines[i:i+50]
            years=[]
            for s in window[:12]:
                years += year_re.findall(s)
            yrs=len(re.findall(r'\\b(?:19|20)\\d{2}\\b','\\n'.join(window[:15])))
            amounts=count_amountish(window[:35])
            dots=sum('....' in x for x in window[:20])
            score=yrs*10+amounts-dots
            cands.append((score,i,strip(lines[i])))
    if not cands:
        return None
    cands.sort(key=lambda x:(x[0],x[1]))
    return cands[-1][1]

def section_lines(lines, start, max_len=220):
    if start is None: return []
    out=[]
    for s in lines[start:start+max_len]:
        out.append(s)
        if strip(s).lower().startswith('see accompanying notes'):
            break
    return out

def parse_years(sec, nmax=3):
    years=[]
    for s in sec[:18]:
        for y in re.findall(r'\\b(?:19|20)\\d{2}\\b', s):
            if y not in years:
                years.append(y)
    if len(years)>nmax:
        # keep a consecutive-looking run of last nmax if too many from title dates
        years=years[-nmax:]
    return [int(y) for y in years]

def extract_value_list(sec, idx, ncols):
    vals=[]
    for j in range(idx, min(len(sec), idx+12)):
        s=strip(sec[j])
        if not s or s=='"'$'"':
            continue
        # remove leading label text on first line
        if j==idx:
            # get remainder after first numeric if any
            tokens=amount_token_re.findall(s)
        else:
            tokens=amount_token_re.findall(s)
        for tok in tokens:
            tok=tok.strip()
            if not tok or tok=='"'$'"':
                continue
            if tok in {'-', '—'}:
                vals.append('0')
            elif re.fullmatch(r'\\(?\\d[\\d,]*\\.?\\d*\\)?', tok):
                vals.append(tok)
            if len(vals)>=ncols:
                return vals
    return vals

def find_row(sec, labels, col_idx, ncols, prefer='first', require_liability=False):
    matches=[]
    sec_low=[strip(s).lower() for s in sec]
    start_i=0
    if require_liability:
        for i,s in enumerate(sec_low):
            if 'liabilities' in s:
                start_i=i
                break
    for i,s in enumerate(sec_low[start_i:], start_i):
        if any(lbl in s for lbl in labels):
            vals=extract_value_list(sec, i, ncols)
            if len(vals)>=ncols:
                matches.append((i,s,vals[col_idx],vals))
    if not matches:
        return None
    if prefer=='last':
        return matches[-1][2]
    return matches[0][2]

# improved cover extraction helpers

def header_end(lines):
    for i,l in enumerate(lines[:350]):
        if 'DOCUMENTS INCORPORATED BY REFERENCE' in l.upper():
            return i
    return min(len(lines),250)


def prev_nonempty(lines,i):
    for j in range(i-1,-1,-1):
        s=strip(lines[j])
        if s:
            return s,j
    return None,None

def next_nonempty(lines,i):
    for j in range(i+1,len(lines)):
        s=strip(lines[j])
        if s:
            return s,j
    return None,None


def extract_name(lines, doc_name):
    end=header_end(lines)
    for i,l in enumerate(lines[:end]):
        if 'Exact name of registrant as specified in its charter' in l or 'Exact name of Registrant as specified in its charter' in l:
            s,j=prev_nonempty(lines,i)
            if s and 'Commission File' not in s and 'For the transition period' not in s:
                return s
    # fallback search exact company in early lines
    key=doc_name.rsplit('_',2)[0]
    fb=company_fallbacks.get(key)
    if fb:
        return fb
    for s in lines[:80]:
        t=strip(s)
        if t.isupper() and 'INC' in t or 'CORPORATION' in t or 'PLC' in t:
            return t
    return 'NOT_FOUND'


def extract_phone(lines):
    end=header_end(lines)
    for i,l in enumerate(lines[:end]):
        if 'telephone number' in l.lower():
            for cand in [l]+[lines[j] for j in range(max(0,i-2), min(end,i+3))]:
                m=phone_re.search(cand)
                if m:
                    p=m.group(1).strip()
                    if not p.startswith('+') and not p.startswith('(') and p[0].isdigit():
                        p='('+p
                    return p
    return 'NOT_FOUND'


def extract_state_ein(lines):
    end=header_end(lines)
    state=ein=None
    for i,l in enumerate(lines[:end]):
        ll=l.lower()
        if 'state or other jurisdiction' in ll or 'state or other jurisdiction of incorporation' in ll or ll.strip()=='state or other jurisdiction of':
            s,_=prev_nonempty(lines,i)
            if s and not ein_re.search(s) and not s.startswith('('):
                state=s
        if 'employer identification no' in ll or 'employer identification number' in ll:
            # prefer previous line with EIN; if line itself has it use that
            m=ein_re.search(l)
            if m: ein=m.group(0)
            else:
                s,_=prev_nonempty(lines,i)
                if s:
                    m=ein_re.search(s)
                    if m: ein=m.group(0)
    if not ein:
        m=ein_re.search('\\n'.join(lines[:end]))
        if m: ein=m.group(0)
    return f'{state}; {ein}' if state and ein else 'NOT_FOUND'


def extract_address(lines):
    end=header_end(lines)
    for i,l in enumerate(lines[:end]):
        ll=l.lower()
        if 'address of principal executive offices' in ll or 'address and telephone number' in ll:
            parts=[]
            for j in range(i-1, max(-1,i-8), -1):
                s=strip(lines[j])
                if not s:
                    if parts: break
                    continue
                if s.startswith('(') or 'identification no' in s.lower() or 'incorporation or organization' in s.lower():
                    break
                if ein_re.search(s):
                    break
                if 'telephone number' in s.lower() or phone_re.search(s):
                    continue
                parts.append(s)
            parts=list(reversed(parts))
            # if zip line comes after label
            for j in range(i+1, min(end,i+4)):
                s=strip(lines[j])
                if not s: continue
                if s.startswith('('):
                    break
                if 'telephone number' in s.lower() or phone_re.search(s):
                    break
                parts.append(s)
            if parts:
                return ', '.join(parts)
    # fallback: lines between EIN label and phone
    ein_idx=phone_idx=None
    for i,l in enumerate(lines[:end]):
        if ein_idx is None and 'employer identification' in l.lower(): ein_idx=i
        if phone_idx is None and 'telephone number' in l.lower(): phone_idx=i
    if ein_idx is not None and phone_idx is not None and phone_idx>ein_idx:
        parts=[]
        for s in lines[ein_idx+1:phone_idx]:
            t=strip(s)
            if not t or t.startswith('(') or ein_re.search(t): continue
            parts.append(t)
        if parts:
            return ', '.join(parts)
    return 'NOT_FOUND'


def extract_trading(lines, text):
    end=header_end(lines)
    start=None
    stop=None
    for i,l in enumerate(lines[:end]):
        ll=l.lower()
        if 'securities registered pursuant to section' in ll and '12(b)' in ll:
            start=i
        elif start is not None and 'securities registered pursuant to section' in ll and '12(g)' in ll:
            stop=i
            break
    block=[strip(x) for x in lines[start+1:stop] if strip(x)] if start is not None and stop is not None else []
    pairs=[]
    exch_keywords=['nasdaq','new york stock exchange']
    for i,s in enumerate(block):
        if any(k in s.lower() for k in exch_keywords):
            sym=''
            # previous non-header non-title line is often symbol
            for j in range(i-1,-1,-1):
                p=block[j]
                if p.startswith('(') or 'trading symbol' in p.lower() or 'title of' in p.lower() or 'name of' in p.lower() or 'common stock' in p.lower() or 'ordinary shares' in p.lower() or 'notes due' in p.lower() or 'par value' in p.lower():
                    continue
                sym=p
                break
            if sym and sym not in {'-','—','None'}:
                pairs.append((sym.rstrip('.'), s))
    if not pairs:
        m=re.search(r'ticker symbol\\s+\"?([A-Z./-]+)\"?', text[:50000], re.I) or re.search(r'under the symbol\\s+\"?([A-Z./-]+)\"?', text[:50000], re.I)
        exch=''
        if 'nasdaq' in text[:6000].lower():
            if 'global select market' in text[:6000].lower(): exch='The Nasdaq Global Select Market' if 'the nasdaq global select market' in text[:6000].lower() else 'Nasdaq Global Select Market'
            elif 'stock market llc' in text[:6000].lower(): exch='The Nasdaq Stock Market LLC'
            else: exch='NASDAQ'
        elif 'new york stock exchange' in text[:6000].lower():
            exch='New York Stock Exchange'
        if m and exch:
            pairs=[(m.group(1).rstrip('.'), exch)]
    out=[]; seen=set()
    for sym,exch in pairs:
        key=(sym,exch)
        if key not in seen:
            seen.add(key)
            out.append(f'{sym} - {exch}')
    return '; '.join(out) if out else 'NOT_FOUND'


def extract_shares(lines):
    end=header_end(lines)
    header='\\n'.join(lines[:end])
    # same-line patterns
    pats=[
        r'([0-9][0-9,\\.]+)\\s+shares of common stock["'^'"\\n]{0,100}?outstanding',
        r'As of ["'^.'"\\n]{0,100}?,\\s*the registrant had\\s*([0-9][0-9,\\.]+)\\s+shares',
        r'The number of shares of the registrant["'^'"\\n]{0,100}?outstanding["'^'"\\n]{0,50}?was\\s*([0-9][0-9,\\.]+)',
        r'As of ["'^.'"\\n]{0,100}?,\\s*the number of shares["'^'"\\n]{0,120}?were[: ]+\\s*([0-9][0-9,\\.]+)',
    ]
    for pat in pats:
        m=re.search(pat, header, re.I|re.S)
        if m:
            return m.group(1).rstrip('.')
    # line-oriented fallback around outstanding section
    for i,l in enumerate(lines[:end]):
        ll=l.lower()
        if 'outstanding' in ll and 'shares' in ll:
            block=[strip(x) for x in lines[i:i+12] if strip(x)]
            nums=[]
            for s in block:
                nums += re.findall(r'\\b[0-9][0-9,\\.]{3,}\\b', s)
            nums=[n.rstrip('.') for n in nums if not re.fullmatch(r'19\\d{2}|20\\d{2}', n)]
            if nums:
                return nums[-1]
    return 'NOT_FOUND'

results=[]
for d in data['documents']:
    text=normalize_text(Path(d['doc_path']).read_text(errors='ignore'))
    lines=text.splitlines()
    inc_start=find_section_start(lines, income_headers)
    bal_start=find_section_start(lines, balance_headers)
    inc_sec=section_lines(lines, inc_start)
    bal_sec=section_lines(lines, bal_start)
    inc_years=parse_years(inc_sec,3)
    bal_years=parse_years(bal_sec,2)
    inc_cols=max(1,len(inc_years))
    bal_cols=max(1,len(bal_years))
    inc_idx=inc_years.index(max(inc_years)) if inc_years else 0
    bal_idx=bal_years.index(max(bal_years)) if bal_years else 0
    revenue=find_row(inc_sec,revenue_labels,inc_idx,inc_cols,'first') or 'NOT_FOUND'
    net=find_row(inc_sec,net_labels,inc_idx,inc_cols,'last') or 'NOT_FOUND'
    assets=find_row(bal_sec,assets_labels,bal_idx,bal_cols,'first') or 'NOT_FOUND'
    debt=find_row(bal_sec,debt_labels,bal_idx,bal_cols,'last',require_liability=True) or 'NOT_FOUND'
    results.append({
        'doc':d['doc_name'],'name':extract_name(lines,d['doc_name']),'phone':extract_phone(lines),'state_ein':extract_state_ein(lines),'address':extract_address(lines),'trading':extract_trading(lines,text),'shares':extract_shares(lines),'revenue':revenue,'net':net,'assets':assets,'debt':debt,'inc_start':inc_start,'bal_start':bal_start,'inc_years':inc_years,'bal_years':bal_years
    })

for r in results:
    bad=[k for k in ['name','phone','state_ein','address','trading','shares','revenue','net','assets','debt'] if r[k]=='NOT_FOUND' or r[k] in {',','.', '(1)'}]
    if bad:
        print(r['doc'], 'BAD', bad, {k:r[k] for k in bad})
PY"

