amount_token_re=re.compile(r'\\(?\\d[\\d,]*\\.?\\d*\\)?|—|-')

INCOME_HEADERS={'consolidated statements of operations','consolidated statements of income','consolidated statements of earnings','statements of consolidated income','consolidated statement of earnings'}
BAL_HEADERS={'consolidated balance sheets','consolidated statements of financial position'}

