assets_labels=['total assets']
debt_labels=['total long-term debt','long-term debt and finance lease liabilities','long-term debt, net of current portion','long-term debt, less current portion','long-term debt excluding current installments','long-term debt excluding current maturities','long-term debt','long-term borrowings','term debt','debt']

