    c=0
    for line in lines:
        line=s(line)
        if re.fullmatch(r'\\"'$?'"\\s*\\(?\\d[\\d,]*\\.?\\d*\\)?%?', line): c+=1
        elif line in {'—','-'}: c+=1
    return c

def find_actual_start(lines, header_set, kind):
    cands=[]
    for i,line in enumerate(lines):
        if nl(line) in header_set:
            window=lines[i:i+45]
            score=0
            if any('in million' in nl(x) or 'in thousand' in nl(x) or 'dollars in million' in nl(x) or '"'$ and shares in million'"' in nl(x) for x in window[:6]):
                score+=20
            if any('years ended' in nl(x) or 'year ended' in nl(x) or 'fiscal years ended' in nl(x) for x in window[:6]):
                score+=15
            if kind=='balance' and any(nl(x) in {'assets','liabilities and stockholders\\' equity','liabilities and shareholders’ equity','liabilities and shareholders\\' equity','liabilities and equity'} for x in window[:10]):
                score+=20
            if kind=='income' and any(lbl in nl(x) for lbl in ['revenue','net sales','sales to customers','net revenue','revenues'] for x in window[4:20]):
                score+=20
            year_count=len(re.findall(r'\\b(?:19|20)\\d{2}\\b','\\n'.join(window[:14])))
            score += year_count*3 + count_amountish(window[:35])
            # penalize toc/exhibit style references
            if any('for the years ended' in nl(x) and x"'!=line for x in window[:2]):
                score-=10
            cands.append((score,i))
    if not cands:
        return None
    return max(cands)[1]

