    if start is None: return []
    out=[]
    for line in lines[start:start+max_len]:
        out.append(line)
        if nl(line).startswith('"'see accompanying notes'):
            break
    return out

def parse_years(section,max_cols):
    years=[]
    for line in section[:16]:
        for y in re.findall(r'\\b(?:19|20)\\d{2}\\b', line):
            if y not in years:
                years.append(y)
    if len(years)>max_cols:
        # prefer last max_cols if a title date precedes the column labels
        years=years[-max_cols:]
    return [int(y) for y in years]

def extract_values_from(section,row_idx,ncols):
    vals=[]
    for j in range(row_idx,row_idx+12):
        if j>=len(section): break
        line=s(section[j])
        if not line or line=='"'$'"':
