        toks=amount_token_re.findall(line)
        for tok in toks:
            tok=tok.strip()
            if tok in {'-','—'}:
                vals.append('0')
            elif re.fullmatch(r'\\(?\\d[\\d,]*\\.?\\d*\\)?', tok):
                vals.append(tok)
            if len(vals)>=ncols:
                return vals
    return vals

def pick_row(section, labels, col_idx, ncols, prefer='first', min_pos=0):
    hits=[]
    for i,line in enumerate(section[min_pos:], start=min_pos):
        l=nl(line)
        if 'per share' in l:
            continue
        if any(lbl in l for lbl in labels):
            vals=extract_values_from(section,i,ncols)
            if len(vals)>=ncols:
                hits.append((i,l,vals[col_idx],vals))
    if not hits:
        return None
    return (hits[-1] if prefer=='last' else hits[0])[2]

samples=['ADOBE_2022_10K','APPLE_2022_10K','BESTBUY_2023_10K','BOEING_2022_10K','GENERALMILLS_2022_10K','NIKE_2021_10K','INTEL_2022_10K','AMAZON_2022_10K','AMD_2022_10K']
for doc in samples:
    text=norm_text((Path('/mnt/data/LSF/data/financebench/text')/f'{doc}.txt').read_text(errors='ignore'))
    lines=text.splitlines()
    istart=find_actual_start(lines,INCOME_HEADERS,'income')
