    rev=pick_row(isec,revenue_labels,iidx,len(iy),'first')
    net=pick_row(isec,net_labels,iidx,len(iy),'last')
    assets=pick_row(bsec,assets_labels,bidx,len(by),'first')
    debt=pick_row(bsec,debt_labels,bidx,len(by),'last',min_pos)
    print(doc,'istart',istart,'iy',iy,'rev',rev,'net',net,'bstart',bstart,'by',by,'assets',assets,'debt',debt)
